A command handler:
Loads the aggregate by replaying its events.
Validates the command against current state.
Generates new events.
Appends them with the next sequential version.
async function shipOrder(orderId, cmd) {
// load events
const events = await db.collection('events')
.find({ aggregate: 'order', aggregate_id: orderId })
.sort({ version: 1 })
.toArray();
if (!events.length) throw new Error('order not found');
// fold to current state
const state = events.reduce(apply, {});
// validate
if (state.status !== 'paid') throw new Error('not paid');
// produce new events
const newEvent = {
aggregate: 'order',
aggregate_id: orderId,
version: events[events.length - 1].version + 1,
event_type: 'order.shipped',
payload: { tracking: cmd.tracking, carrier: cmd.carrier, shipped_at: new Date() },
metadata: cmd.metadata,
occurred_at: new Date(),
};
// append (unique index on (aggregate, aggregate_id, version) blocks conflicting writes)
await db.collection('events').insertOne(newEvent);
}
function apply(state, event) {
switch (event.event_type) {
case 'order.created': return { ...state, status: 'pending', items: event.payload.items, total: event.payload.total };
case 'order.paid': return { ...state, status: 'paid' };
case 'order.shipped': return { ...state, status: 'shipped', tracking: event.payload.tracking };
case 'order.cancelled': return { ...state, status: 'cancelled' };
default: return state;
}
}
Concurrency: two handlers trying to append version: N for the same aggregate → one wins, the other gets E11000 duplicate key. The losing handler retries by re-loading the aggregate (now at version N+1) + reapplying validation.

